let data = '';
process.stdin.on('data', (chunk) => (data += chunk));
process.stdin.on('end', () => {
  const lines = data.split('\n').map((s) => s.trim()).filter(Boolean);
  const r = Number(lines[0]);
  const routes = lines.slice(1, 1 + r).map((l) => l.split(' '));
  const requests = lines.slice(1 + r).map((l) => l.split(' '));

  function match(pattern, path) {
    const a = pattern.split('/');
    const b = path.split('/');
    if (a.length !== b.length) return null;
    const params = [];
    for (let i = 0; i < a.length; i++) {
      if (a[i].startsWith(':')) params.push(a[i].slice(1) + '=' + b[i]);
      else if (a[i] !== b[i]) return null;
    }
    return params;
  }

  for (const [method, path] of requests) {
    let out = null;
    let pathExists = false;
    for (const [m, pattern, name] of routes) {
      const p = match(pattern, path);
      if (!p) continue;
      pathExists = true;
      if (m === method) { out = [name, ...p].join(' '); break; }
    }
    if (!out) out = pathExists ? '405 Method Not Allowed' : '404 Not Found';
    console.log(out);
  }
});

