let data = '';
process.stdin.on('data', (chunk) => (data += chunk));
process.stdin.on('end', () => {
  function reply(code, obj) {
    console.log(code);
    console.log(JSON.stringify(obj));
  }
  let body;
  try {
    body = JSON.parse(data);
  } catch (e) {
    return reply(400, { error: 'invalid JSON' });
  }
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    return reply(400, { error: 'invalid JSON' });
  }
  if (typeof body.name !== 'string' || body.name.trim() === '') {
    return reply(422, { error: 'name is required' });
  }
  if (!Number.isInteger(body.age) || body.age < 0 || body.age > 150) {
    return reply(422, { error: 'age must be an integer from 0 to 150' });
  }
  reply(201, { id: 1, name: body.name.trim(), age: body.age });
});

