let data = '';
process.stdin.on('data', (chunk) => (data += chunk));
process.stdin.on('end', () => {
  const lines = data.split('\n').map((s) => s.trim()).filter(Boolean);
  const counts = { 2: 0, 3: 0, 4: 0, 5: 0 };
  let total = 0;
  let slow = null;
  for (const line of lines) {
    const [, , path, status, dur] = line.split(' ');
    const ms = parseInt(dur, 10);
    const fam = Math.floor(Number(status) / 100);
    if (fam in counts) counts[fam]++;
    total += ms;
    if (!slow || ms > slow.ms) slow = { path, ms };
  }
  console.log('requests: ' + lines.length);
  for (const f of [2, 3, 4, 5]) console.log(f + 'xx: ' + counts[f]);
  console.log('avg_ms: ' + Math.round(total / lines.length));
  console.log('slowest: ' + slow.path + ' (' + slow.ms + 'ms)');
});
